SELECT 0, '身材管理', '/admin/fitness', '', 'ele-Bicycle', 1, 60, 1, 1, UNIX_TIMESTAMP(), UNIX_TIMESTAMP(), 0
WHERE NOT EXISTS (SELECT 1 FROM `admin_menu` WHERE `path` = '/admin/fitness' AND `deleted_at` = 0);
SET @fitness_dir_id = (SELECT `id` FROM `admin_menu` WHERE `path` = '/admin/fitness' AND `deleted_at` = 0 LIMIT 1);

