-- 4. 权限-菜单关联（页面 → list 权限，按钮 → 对应操作权限）
INSERT INTO `admin_permission_menu` (`permission_id`, `menu_id`, `created_at`, `updated_at`)
SELECT p.`id`, m.`id`, UNIX_TIMESTAMP(), UNIX_TIMESTAMP()
FROM `admin_permission` p
JOIN `admin_menu` m ON m.`deleted_at` = 0 AND (
  (p.`code` = 'fitness_template:list' AND m.`path` = '/admin/fitness/template')
  OR (p.`code` = 'fitness_template:create' AND m.`parent_id` = (SELECT pm.`id` FROM `admin_menu` pm WHERE pm.`path` = '/admin/fitness/template' AND pm.`deleted_at` = 0 LIMIT 1) AND m.`name` = '计划模板 新增按钮')
  OR (p.`code` = 'fitness_template:update' AND m.`parent_id` = (SELECT pm.`id` FROM `admin_menu` pm WHERE pm.`path` = '/admin/fitness/template' AND pm.`deleted_at` = 0 LIMIT 1) AND m.`name` = '计划模板 编辑按钮')
  OR (p.`code` = 'fitness_template:delete' AND m.`parent_id` = (SELECT pm.`id` FROM `admin_menu` pm WHERE pm.`path` = '/admin/fitness/template' AND pm.`deleted_at` = 0 LIMIT 1) AND m.`name` = '计划模板 删除按钮')
  OR (p.`code` = 'fitness_tip:list' AND m.`path` = '/admin/fitness/tip')
  OR (p.`code` = 'fitness_tip:create' AND m.`parent_id` = (SELECT pm.`id` FROM `admin_menu` pm WHERE pm.`path` = '/admin/fitness/tip' AND pm.`deleted_at` = 0 LIMIT 1) AND m.`name` = '通用提示 新增按钮')
  OR (p.`code` = 'fitness_tip:update' AND m.`parent_id` = (SELECT pm.`id` FROM `admin_menu` pm WHERE pm.`path` = '/admin/fitness/tip' AND pm.`deleted_at` = 0 LIMIT 1) AND m.`name` = '通用提示 编辑按钮')
  OR (p.`code` = 'fitness_tip:delete' AND m.`parent_id` = (SELECT pm.`id` FROM `admin_menu` pm WHERE pm.`path` = '/admin/fitness/tip' AND pm.`deleted_at` = 0 LIMIT 1) AND m.`name` = '通用提示 删除按钮')
  OR (p.`code` = 'fitness_member:list' AND m.`path` = '/admin/fitness/member')
  OR (p.`code` = 'fitness_member:assign' AND m.`parent_id` = (SELECT pm.`id` FROM `admin_menu` pm WHERE pm.`path` = '/admin/fitness/member' AND pm.`deleted_at` = 0 LIMIT 1) AND m.`name` = '使用者 指定模板按钮')
  OR (p.`code` = 'fitness_stats:list' AND m.`path` = '/admin/fitness/stats')
  OR (p.`code` = 'fitness_stats:export' AND m.`parent_id` = (SELECT pm.`id` FROM `admin_menu` pm WHERE pm.`path` = '/admin/fitness/stats' AND pm.`deleted_at` = 0 LIMIT 1) AND m.`name` = '打卡统计 导出按钮')
)
WHERE p.`deleted_at` = 0
ON DUPLICATE KEY UPDATE `updated_at`=UNIX_TIMESTAMP();

-- 5. 权限-接口关联
INSERT INTO `admin_permission_api` (`permission_id`, `api_id`, `created_at`, `updated_at`)
SELECT p.`id`, a.`id`, UNIX_TIMESTAMP(), UNIX_TIMESTAMP()
FROM `admin_permission` p
JOIN `admin_api` a ON a.`deleted_at` = 0 AND (
  (p.`code` = 'fitness_template:list' AND a.`method` = 'GET' AND a.`path` = '/api/v1/fitness/templates')
  OR (p.`code` = 'fitness_member:assign' AND a.`method` = 'GET' AND a.`path` = '/api/v1/fitness/templates')
  OR (p.`code` = 'fitness_template:create' AND a.`method` = 'POST' AND a.`path` = '/api/v1/fitness/templates')
  OR (p.`code` = 'fitness_template:update' AND a.`method` = 'PUT' AND a.`path` = '/api/v1/fitness/templates')
  OR (p.`code` = 'fitness_template:delete' AND a.`method` = 'DELETE' AND a.`path` = '/api/v1/fitness/templates')
  OR (p.`code` = 'fitness_template:list' AND a.`method` = 'GET' AND a.`path` = '/api/v1/fitness/template-days')
  OR (p.`code` = 'fitness_template:update' AND a.`method` = 'PUT' AND a.`path` = '/api/v1/fitness/template-days')
  OR (p.`code` = 'fitness_template:update' AND a.`method` = 'DELETE' AND a.`path` = '/api/v1/fitness/template-days')
  OR (p.`code` = 'fitness_tip:list' AND a.`method` = 'GET' AND a.`path` = '/api/v1/fitness/tips')
  OR (p.`code` = 'fitness_tip:create' AND a.`method` = 'POST' AND a.`path` = '/api/v1/fitness/tips')
  OR (p.`code` = 'fitness_tip:update' AND a.`method` = 'PUT' AND a.`path` = '/api/v1/fitness/tips')
  OR (p.`code` = 'fitness_tip:delete' AND a.`method` = 'DELETE' AND a.`path` = '/api/v1/fitness/tips')
  OR (p.`code` = 'fitness_member:list' AND a.`method` = 'GET' AND a.`path` = '/api/v1/fitness/members')
  OR (p.`code` = 'fitness_member:assign' AND a.`method` = 'POST' AND a.`path` = '/api/v1/fitness/members/template')
  OR (p.`code` = 'fitness_member:list' AND a.`method` = 'GET' AND a.`path` = '/api/v1/fitness/members/switches')
  OR (p.`code` = 'fitness_stats:list' AND a.`method` = 'GET' AND a.`path` = '/api/v1/fitness/members/switches')
  OR (p.`code` = 'fitness_stats:list' AND a.`method` = 'GET' AND a.`path` = '/api/v1/fitness/stats/overview')
  OR (p.`code` = 'fitness_stats:list' AND a.`method` = 'GET' AND a.`path` = '/api/v1/fitness/stats/checkins')
  OR (p.`code` = 'fitness_stats:list' AND a.`method` = 'GET' AND a.`path` = '/api/v1/fitness/stats/member')
  OR (p.`code` = 'fitness_stats:export' AND a.`method` = 'GET' AND a.`path` = '/api/v1/fitness/stats/checkins/export')
)
WHERE p.`deleted_at` = 0
ON DUPLICATE KEY UPDATE `updated_at`=UNIX_TIMESTAMP();

