-- 7. 计划模板（7 套）
-- 通用口径：力量2-4次/周 + 中等强度有氧约150分钟/周；热量缺口300-500千卡（维持期除外）；
-- 蛋白质1.2-1.6g/kg；减重速度每周体重的0.5-1%。作息：10-21点上班、通勤30分钟、24小时健身房、
-- 默认08:00-09:00训练；早餐09:00、午餐12:30、加餐16:00、晚餐17:30-18:30、21:30到家不吃正餐；
-- 三餐全在公司解决不做饭（早餐便利店/早餐摊，午晚饭外卖/食堂），每餐给「怎么点」和2-3个替换。
INSERT INTO `fitness_template` (`code`, `name`, `level`, `stage`, `summary`, `daily_kcal`, `daily_protein`, `sort`, `status`, `created_at`, `updated_at`, `deleted_at`)
VALUES
  ('starter', '零基础入门', 1, '第1-4周', '每周3次自重/轻器械全身训练（每次30-40分钟）+ 2次快走，日均6000步。先养成习惯、学会动作，不追求重量。热量缺口300-500千卡，蛋白质约1.2-1.6g/kg。', 1850, 110, 1, 1, UNIX_TIMESTAMP(), UNIX_TIMESTAMP(), 0),
  ('standard', '减脂标准', 2, '第5-12周', '周一三五全身力量45分钟+快走15分钟（深蹲、罗马尼亚硬拉、卧推/俯卧撑、哑铃划船、站姿推举、平板支撑），周二六低中强度有氧30-40分钟，周四日休息或散步，日均8000步。', 1850, 120, 2, 1, UNIX_TIMESTAMP(), UNIX_TIMESTAMP(), 0),
  ('advanced', '减脂进阶', 3, '第13周起', '上下肢分化4练（周一上肢A、周二下肢A、周四上肢B、周五下肢B）+ 2次有氧（周三稳态、周六间歇），周日休息，日均10000步。', 1850, 125, 3, 1, UNIX_TIMESTAMP(), UNIX_TIMESTAMP(), 0),
  ('evening', '晚练版', 0, '早上起不来时', '结构同减脂标准，训练挪到21:45-22:45（24小时健身房）。晚饭提前到18:00，到家后不吃正餐，练后一杯牛奶+一个蛋，23:45前睡。', 1900, 120, 4, 1, UNIX_TIMESTAMP(), UNIX_TIMESTAMP(), 0),
  ('busy', '忙碌周/出差', 0, '加班或出差周', '每周3次20分钟自重循环（家里/酒店都能做），其余天多走路，日均7000步。重点放在控制外卖：主食减半、酱汁分装、不喝汤。', 1850, 110, 5, 1, UNIX_TIMESTAMP(), UNIX_TIMESTAMP(), 0),
  ('plateau', '平台期调整', 0, '体重2周不降时（建议用2周）', '体重连续2周不降时用2周：力量换一批动作，有氧次数和时长增加，日均10000步，午晚饭主食再少一点（热量比减脂标准再低约150千卡）。2周后回原模板。', 1700, 125, 6, 1, UNIX_TIMESTAMP(), UNIX_TIMESTAMP(), 0),
  ('maintain', '维持期', 0, '达到目标体重后', '达到目标后吃到维持热量（约2200千卡），每周3次全身力量保持肌肉，其余天正常活动，日均8000步。每周体重波动在±1kg内即可。', 2200, 100, 7, 1, UNIX_TIMESTAMP(), UNIX_TIMESTAMP(), 0)
ON DUPLICATE KEY UPDATE `id`=`id`;

-- 8. 模板每日内容（每套 7 天，weekday 1=周一 … 7=周日）
-- 零基础入门（starter）
INSERT INTO `fitness_template_day` (`template_id`, `weekday`, `plan_date`, `training_type`, `training_time`, `step_goal`, `warmup`, `exercises`, `stretch`, `training_note`, `meals`, `tip`, `created_at`, `updated_at`, `deleted_at`)
SELECT t.`id`, 1, '', 1, '08:00-09:00', 6000, '原地踏步3分钟 + 开合跳20次 + 髋绕环、肩绕环各10次', '[{"name":"自重深蹲","sets":3,"reps":"10-12","duration":"","note":"膝盖和脚尖同向，蹲到大腿接近水平"},{"name":"跪姿俯卧撑","sets":3,"reps":"6-10","duration":"","note":""},{"name":"弹力带划船","sets":3,"reps":"10-12","duration":"","note":"没有弹力带用轻哑铃俯身划船"},{"name":"臀桥","sets":3,"reps":"12-15","duration":"","note":""},{"name":"平板支撑","sets":3,"reps":"","duration":"20-30秒","note":""}]', '大腿前后侧、臀部、胸肩各拉伸30秒，共5-8分钟', '第一周以学动作为主，每组结束还能再做3次左右就对了；组间休息60秒', '[{"slot":"breakfast","time":"09:00","place":"便利店","food":"茶叶蛋2个 + 无糖豆浆1盒 + 全麦面包1片","portion":"蛋2个、豆浆250ml、面包1片","kcal":380,"protein":25,"howToOrder":"热柜拿茶叶蛋；冷柜豆浆认准「无糖」；面包看配料表第一位是全麦粉","alternatives":["鸡蛋火腿三明治1个 + 无糖豆浆","玉米1根 + 茶叶蛋2个 + 纯牛奶"]},{"slot":"lunch","time":"12:30","place":"外卖","food":"轻食鸡胸肉沙拉碗 + 糙米饭","portion":"鸡胸150g、蔬菜1大份、米饭半份（约100g）","kcal":550,"protein":40,"howToOrder":"蛋白选鸡胸/牛肉，酱汁选油醋汁并备注「酱单独放」只用一半；主食加糙米","alternatives":["牛肉藜麦碗（酱单独放）","虾仁滑蛋饭（米饭减半）+ 一份烫青菜"]},{"slot":"snack","time":"16:00","place":"工位","food":"无糖酸奶1杯 + 苹果1个","portion":"酸奶100g、苹果1个","kcal":180,"protein":8,"howToOrder":"便利店冷柜选无添加糖酸奶","alternatives":["纯牛奶250ml + 橙子1个","茶叶蛋1个 + 黄瓜1根"]},{"slot":"dinner","time":"17:30-18:30","place":"食堂","food":"清蒸鱼 + 两份青菜 + 杂粮饭","portion":"鱼1份、青菜2份、米饭半份（约100g）","kcal":500,"protein":35,"howToOrder":"没有清蒸鱼就选白灼虾/卤牛肉；青菜挑少油的；杂粮饭盛半碗","alternatives":["卤牛肉 + 两素 + 米饭减半","番茄炒蛋 + 白切鸡 + 青菜（不要米饭换玉米）"]},{"slot":"after_home","time":"21:30","place":"家里","food":"纯牛奶1盒","portion":"250ml","kcal":150,"protein":8,"howToOrder":"到家不吃正餐，饿就喝牛奶","alternatives":["无糖酸奶1杯","水煮蛋2个"]}]', '周一：先把动作做标准，重量不重要', UNIX_TIMESTAMP(), UNIX_TIMESTAMP(), 0
FROM `fitness_template` t WHERE t.`code` = 'starter' AND t.`deleted_at` = 0
ON DUPLICATE KEY UPDATE `fitness_template_day`.`id` = `fitness_template_day`.`id`;
INSERT INTO `fitness_template_day` (`template_id`, `weekday`, `plan_date`, `training_type`, `training_time`, `step_goal`, `warmup`, `exercises`, `stretch`, `training_note`, `meals`, `tip`, `created_at`, `updated_at`, `deleted_at`)
SELECT t.`id`, 2, '', 2, '08:00-09:00', 6000, '慢走3-5分钟，逐渐加速到目标强度', '[{"name":"快走（跑步机或户外）","sets":0,"reps":"","duration":"30分钟","note":"中等强度：能说完整句子但唱不了歌"}]', '小腿、大腿前后侧各拉伸30秒', '坡度0-3、速度5-6km/h，走完不喘到说不出话即可', '[{"slot":"breakfast","time":"09:00","place":"早餐摊","food":"鸡蛋灌饼（不刷甜面酱、少油）+ 无糖豆浆","portion":"灌饼1个、豆浆1杯","kcal":420,"protein":18,"howToOrder":"跟摊主说「酱少刷、不要辣条/火腿肠」，加一个蛋；豆浆要不加糖的","alternatives":["杂粮煎饼（加蛋不加薄脆）+ 无糖豆浆","肉包1个 + 茶叶蛋1个 + 无糖豆浆"]},{"slot":"lunch","time":"12:30","place":"外卖","food":"清汤牛肉面（加牛肉、面减半）+ 烫青菜","portion":"牛肉加量、面条半份、青菜1份","kcal":600,"protein":35,"howToOrder":"选清汤不选红油，「加一份牛肉、面少一半」；汤喝两口就停","alternatives":["番茄牛肉粉（粉减半）","鸡丝凉面换鸡丝汤面（面减半、加蛋）"]},{"slot":"snack","time":"16:00","place":"便利店","food":"即食鸡胸肉1袋","portion":"约100g","kcal":130,"protein":22,"howToOrder":"选原味/黑椒，避开蜜汁、烧烤味（糖多）","alternatives":["茶叶蛋2个","卤豆干1小包 + 纯牛奶"]},{"slot":"dinner","time":"17:30-18:30","place":"外卖","food":"小份酸菜鱼（不喝汤）+ 米饭","portion":"鱼片1份、米饭半份（约100g）","kcal":560,"protein":36,"howToOrder":"选小份/单人份，「少油」；鱼片和菜捞着吃，汤不喝","alternatives":["水煮鱼换清汤鱼片（小份）","番茄龙利鱼饭（米饭减半）"]},{"slot":"after_home","time":"21:30","place":"家里","food":"水煮蛋2个","portion":"2个","kcal":140,"protein":12,"howToOrder":"周末一次煮好一盒放冰箱","alternatives":["纯牛奶1盒","无糖酸奶1杯"]}]', '周二：快走时注意心率，能聊天的强度刚好', UNIX_TIMESTAMP(), UNIX_TIMESTAMP(), 0
FROM `fitness_template` t WHERE t.`code` = 'starter' AND t.`deleted_at` = 0
ON DUPLICATE KEY UPDATE `fitness_template_day`.`id` = `fitness_template_day`.`id`;
INSERT INTO `fitness_template_day` (`template_id`, `weekday`, `plan_date`, `training_type`, `training_time`, `step_goal`, `warmup`, `exercises`, `stretch`, `training_note`, `meals`, `tip`, `created_at`, `updated_at`, `deleted_at`)
SELECT t.`id`, 3, '', 1, '08:00-09:00', 6000, '原地踏步3分钟 + 开合跳20次 + 髋绕环、肩绕环各10次', '[{"name":"扶墙箭步蹲","sets":3,"reps":"8/侧","duration":"","note":""},{"name":"上斜俯卧撑（手扶桌面或史密斯杠）","sets":3,"reps":"8-12","duration":"","note":""},{"name":"轻哑铃罗马尼亚硬拉","sets":3,"reps":"10-12","duration":"","note":"臀部向后推，背保持平直"},{"name":"坐姿哑铃推举（轻）","sets":3,"reps":"10","duration":"","note":""},{"name":"死虫","sets":3,"reps":"8/侧","duration":"","note":""}]', '大腿前后侧、臀部、胸肩各拉伸30秒，共5-8分钟', '比周一换了一组动作，同样留3次余力；硬拉感觉腰酸就降重量', '[{"slot":"breakfast","time":"09:00","place":"便利店","food":"鸡胸肉三明治 + 纯牛奶","portion":"三明治1个、牛奶250ml","kcal":430,"protein":30,"howToOrder":"选夹鸡胸/鸡蛋的三明治，避开沙拉酱很厚、夹炸物的；牛奶选纯牛奶不选乳饮料","alternatives":["金枪鱼饭团1个 + 茶叶蛋1个 + 纯牛奶","即食鸡胸肉1袋 + 全麦面包2片"]},{"slot":"lunch","time":"12:30","place":"外卖","food":"木桶饭（清蒸鱼/香菇鸡 + 青菜）","portion":"主菜1份、青菜1份、米饭半份（约100g）","kcal":600,"protein":36,"howToOrder":"主菜挑清蒸鱼/香菇鸡/番茄牛腩，避开红烧肉/干锅；备注「米饭少一半」","alternatives":["煲仔饭换卤牛肉饭（米饭减半）","日式鸡腿饭（去皮、酱少、米饭减半）"]},{"slot":"snack","time":"16:00","place":"工位","food":"原味坚果1小包 + 无糖豆浆","portion":"坚果20g、豆浆250ml","kcal":210,"protein":10,"howToOrder":"坚果只吃一小包（每日坚果那种），别开大罐","alternatives":["纯牛奶 + 苹果","无糖酸奶 + 香蕉半根"]},{"slot":"dinner","time":"17:30-18:30","place":"外卖","food":"照烧鸡腿饭（去皮、酱少）+ 味增汤","portion":"鸡腿1只、米饭半份（约100g）","kcal":560,"protein":33,"howToOrder":"备注「鸡腿去皮、照烧汁少放、米饭少一半」","alternatives":["日式烤鱼定食（米饭减半）","寿司拼盘8个 + 味增汤"]},{"slot":"after_home","time":"21:30","place":"家里","food":"无糖酸奶1杯","portion":"150g","kcal":120,"protein":7,"howToOrder":"选配料表只有生牛乳+菌种的","alternatives":["纯牛奶1盒","水煮蛋1个 + 黄瓜"]}]', '周三：练完记得吃早饭，蛋白质别省', UNIX_TIMESTAMP(), UNIX_TIMESTAMP(), 0
FROM `fitness_template` t WHERE t.`code` = 'starter' AND t.`deleted_at` = 0
ON DUPLICATE KEY UPDATE `fitness_template_day`.`id` = `fitness_template_day`.`id`;
INSERT INTO `fitness_template_day` (`template_id`, `weekday`, `plan_date`, `training_type`, `training_time`, `step_goal`, `warmup`, `exercises`, `stretch`, `training_note`, `meals`, `tip`, `created_at`, `updated_at`, `deleted_at`)
SELECT t.`id`, 4, '', 3, '', 6000, '', '[{"name":"饭后散步","sets":0,"reps":"","duration":"30分钟","note":"休息日不计入完成率，走够步数就算赢"}]', '', '', '[{"slot":"breakfast","time":"09:00","place":"早餐摊","food":"小笼包4个 + 茶叶蛋1个 + 无糖豆浆","portion":"包子4个、蛋1个、豆浆1杯","kcal":450,"protein":22,"howToOrder":"包子选鲜肉/菜肉的，不要油煎生煎；不蘸醋以外的酱","alternatives":["馄饨1小碗（不加猪油）+ 茶叶蛋1个","菜包2个 + 茶叶蛋2个 + 无糖豆浆"]},{"slot":"lunch","time":"12:30","place":"外卖","food":"黄焖鸡米饭（去皮、汤汁少）","portion":"鸡肉1份、米饭半份（约100g）","kcal":650,"protein":38,"howToOrder":"备注「鸡肉去皮、少汤汁、米饭少一半」，汤汁别拌饭；加一份烫青菜","alternatives":["香菇滑鸡饭（米饭减半）","台式卤肉饭换鸡腿饭（去皮、米饭减半）"]},{"slot":"snack","time":"16:00","place":"工位","food":"纯牛奶 + 全麦饼干2片","portion":"牛奶250ml、饼干2片","kcal":210,"protein":10,"howToOrder":"饼干看配料表第一位是全麦粉、糖不在前三位","alternatives":["无糖酸奶 + 苹果","即食鸡胸肉1袋"]},{"slot":"dinner","time":"17:30-18:30","place":"外卖","food":"宫保鸡丁（少油少糖）+ 蒜蓉西兰花 + 米饭","portion":"鸡丁1份、西兰花1份、米饭半份（约100g）","kcal":560,"protein":34,"howToOrder":"备注「少油少糖、花生少放」；西兰花备注少油","alternatives":["青椒炒牛肉 + 白灼菜心 + 米饭减半","小炒鸡胸肉 + 清炒时蔬 + 米饭减半"]},{"slot":"after_home","time":"21:30","place":"家里","food":"不饿就不吃，喝杯温水","portion":"—","kcal":0,"protein":0,"howToOrder":"真饿了再从替换里选一样","alternatives":["纯牛奶1盒","无糖酸奶1杯"]}]', '周四：休息也是训练的一部分，睡够7小时', UNIX_TIMESTAMP(), UNIX_TIMESTAMP(), 0
FROM `fitness_template` t WHERE t.`code` = 'starter' AND t.`deleted_at` = 0
ON DUPLICATE KEY UPDATE `fitness_template_day`.`id` = `fitness_template_day`.`id`;
