SELECT t.`id`, 5, '', 1, '08:00-09:00', 6000, '原地踏步3分钟 + 开合跳20次 + 髋绕环、肩绕环各10次', '[{"name":"高脚杯深蹲（轻哑铃）","sets":3,"reps":"10","duration":"","note":""},{"name":"跪姿俯卧撑","sets":3,"reps":"8-10","duration":"","note":""},{"name":"高位下拉","sets":3,"reps":"10-12","duration":"","note":""},{"name":"臀桥","sets":3,"reps":"15","duration":"","note":""},{"name":"侧平板支撑","sets":2,"reps":"","duration":"20秒/侧","note":""}]', '大腿前后侧、臀部、胸肩各拉伸30秒，共5-8分钟', '本周最后一练，可以比周一多做1-2次；结束后快走10分钟', '[{"slot":"breakfast","time":"09:00","place":"便利店","food":"鸡肉饭团1个 + 茶叶蛋2个 + 无糖酸奶1杯","portion":"饭团1个、蛋2个、酸奶100g","kcal":440,"protein":26,"howToOrder":"饭团选鸡肉/金枪鱼口味，避开蛋黄酱多的；酸奶看配料表无添加糖","alternatives":["红薯1个 + 茶叶蛋2个 + 纯牛奶","鸡胸肉三明治 + 无糖豆浆"]},{"slot":"lunch","time":"12:30","place":"外卖","food":"广式烧腊饭（白切鸡去皮/叉烧去肥）+ 青菜","portion":"肉1份、青菜1份、米饭半份（约100g）","kcal":650,"protein":38,"howToOrder":"选白切鸡或叉烧，备注「去皮/去肥、酱汁少」；加一份白灼菜心","alternatives":["豉汁蒸排骨饭（米饭减半）+ 青菜","白切鸡饭（去皮）+ 例汤"]},{"slot":"snack","time":"16:00","place":"工位","food":"纯牛奶 + 小香蕉1根","portion":"牛奶250ml、香蕉1根","kcal":200,"protein":9,"howToOrder":"下午犯困别买奶茶，牛奶+水果顶饿","alternatives":["无糖豆浆 + 苹果","无糖酸奶 + 小番茄一盒"]},{"slot":"dinner","time":"17:30-18:30","place":"外卖","food":"牛肉轻食饭（杂粮饭）+ 西兰花","portion":"牛肉120g、西兰花1份、米饭半份（约100g）","kcal":520,"protein":36,"howToOrder":"选卤/煎牛肉，酱单独放；杂粮饭点半份","alternatives":["鸡胸肉轻食饭（酱单独放）","虾仁炒蛋 + 清炒时蔬 + 米饭减半"]},{"slot":"after_home","time":"21:30","place":"家里","food":"纯牛奶 + 水煮蛋1个","portion":"牛奶250ml、蛋1个","kcal":220,"protein":14,"howToOrder":"练得多的日子可以两样都吃","alternatives":["无糖酸奶 + 水煮蛋1个","纯牛奶1盒"]}]', '周五：外卖晚饭按计划点，周末前别放飞', UNIX_TIMESTAMP(), UNIX_TIMESTAMP(), 0
FROM `fitness_template` t WHERE t.`code` = 'starter' AND t.`deleted_at` = 0
