SELECT t.`id`, 3, '', 1, '08:00-09:00', 8000, '跑步机快走5分钟 + 动态拉伸（开合跳、髋绕环、肩绕环各10次）+ 第一个动作空杆/轻重量做2组', '[{"name":"高脚杯深蹲","sets":3,"reps":"10-12","duration":"","note":""},{"name":"哑铃罗马尼亚硬拉","sets":3,"reps":"10-12","duration":"","note":""},{"name":"俯卧撑","sets":3,"reps":"8-12","duration":"","note":"做不够就上斜"},{"name":"单臂哑铃划船","sets":3,"reps":"10-12/侧","duration":"","note":""},{"name":"哑铃站姿推举","sets":3,"reps":"8-12","duration":"","note":""},{"name":"平板支撑","sets":3,"reps":"","duration":"30-45秒","note":""},{"name":"快走","sets":0,"reps":"","duration":"15分钟","note":""}]', '大腿前后侧、臀部、胸肩各拉伸30秒，共5-8分钟', '周三换哑铃版本，动作控制比重量重要；主项3×8-12，每组留1-2次余力；组间休息60-90秒；力量练完接快走15分钟', '[{"slot":"breakfast","time":"09:00","place":"便利店","food":"鸡胸肉三明治 + 纯牛奶","portion":"三明治1个、牛奶250ml","kcal":430,"protein":30,"howToOrder":"选夹鸡胸/鸡蛋的三明治，避开沙拉酱很厚、夹炸物的；牛奶选纯牛奶不选乳饮料","alternatives":["金枪鱼饭团1个 + 茶叶蛋1个 + 纯牛奶","即食鸡胸肉1袋 + 全麦面包2片"]},{"slot":"lunch","time":"12:30","place":"外卖","food":"木桶饭（清蒸鱼/香菇鸡 + 青菜）","portion":"主菜1份、青菜1份、米饭半份（约100g）","kcal":600,"protein":36,"howToOrder":"主菜挑清蒸鱼/香菇鸡/番茄牛腩，避开红烧肉/干锅；备注「米饭少一半」","alternatives":["煲仔饭换卤牛肉饭（米饭减半）","日式鸡腿饭（去皮、酱少、米饭减半）"]},{"slot":"snack","time":"16:00","place":"工位","food":"原味坚果1小包 + 无糖豆浆","portion":"坚果20g、豆浆250ml","kcal":210,"protein":10,"howToOrder":"坚果只吃一小包（每日坚果那种），别开大罐","alternatives":["纯牛奶 + 苹果","无糖酸奶 + 香蕉半根"]},{"slot":"dinner","time":"17:30-18:30","place":"外卖","food":"照烧鸡腿饭（去皮、酱少）+ 味增汤","portion":"鸡腿1只、米饭半份（约100g）","kcal":560,"protein":33,"howToOrder":"备注「鸡腿去皮、照烧汁少放、米饭少一半」","alternatives":["日式烤鱼定食（米饭减半）","寿司拼盘8个 + 味增汤"]},{"slot":"after_home","time":"21:30","place":"家里","food":"无糖酸奶1杯","portion":"150g","kcal":120,"protein":7,"howToOrder":"选配料表只有生牛乳+菌种的","alternatives":["纯牛奶1盒","水煮蛋1个 + 黄瓜"]}]', '周三：哑铃日，左右两侧都要做满', UNIX_TIMESTAMP(), UNIX_TIMESTAMP(), 0
