SELECT t.`id`, 3, '', 2, '08:00-09:00', 10000, '慢走3-5分钟，逐渐加速到目标强度', '[{"name":"稳态有氧（坡度走/椭圆机/单车）","sets":0,"reps":"","duration":"40分钟","note":"中等强度：能说完整句子但唱不了歌"}]', '小腿、大腿前后侧各拉伸30秒', '恢复日，心率保持中低强度，不要练成间歇', '[{"slot":"breakfast","time":"09:00","place":"便利店","food":"鸡胸肉三明治 + 纯牛奶","portion":"三明治1个、牛奶250ml","kcal":430,"protein":30,"howToOrder":"选夹鸡胸/鸡蛋的三明治，避开沙拉酱很厚、夹炸物的；牛奶选纯牛奶不选乳饮料","alternatives":["金枪鱼饭团1个 + 茶叶蛋1个 + 纯牛奶","即食鸡胸肉1袋 + 全麦面包2片"]},{"slot":"lunch","time":"12:30","place":"外卖","food":"木桶饭（清蒸鱼/香菇鸡 + 青菜）","portion":"主菜1份、青菜1份、米饭半份（约100g）","kcal":600,"protein":36,"howToOrder":"主菜挑清蒸鱼/香菇鸡/番茄牛腩，避开红烧肉/干锅；备注「米饭少一半」","alternatives":["煲仔饭换卤牛肉饭（米饭减半）","日式鸡腿饭（去皮、酱少、米饭减半）"]},{"slot":"snack","time":"16:00","place":"工位","food":"原味坚果1小包 + 无糖豆浆","portion":"坚果20g、豆浆250ml","kcal":210,"protein":10,"howToOrder":"坚果只吃一小包（每日坚果那种），别开大罐","alternatives":["纯牛奶 + 苹果","无糖酸奶 + 香蕉半根"]},{"slot":"dinner","time":"17:30-18:30","place":"外卖","food":"照烧鸡腿饭（去皮、酱少）+ 味增汤","portion":"鸡腿1只、米饭半份（约100g）","kcal":560,"protein":33,"howToOrder":"备注「鸡腿去皮、照烧汁少放、米饭少一半」","alternatives":["日式烤鱼定食（米饭减半）","寿司拼盘8个 + 味增汤"]},{"slot":"after_home","time":"21:30","place":"家里","food":"无糖酸奶1杯","portion":"150g","kcal":120,"protein":7,"howToOrder":"选配料表只有生牛乳+菌种的","alternatives":["纯牛奶1盒","水煮蛋1个 + 黄瓜"]}]', '周三：有氧恢复日，别加码', UNIX_TIMESTAMP(), UNIX_TIMESTAMP(), 0
FROM `fitness_template` t WHERE t.`code` = 'advanced' AND t.`deleted_at` = 0
