SELECT t.`id`, 4, '', 1, '08:00-09:00', 10000, '跑步机快走5分钟 + 动态拉伸（开合跳、髋绕环、肩绕环各10次）+ 第一个动作空杆/轻重量做2组', '[{"name":"上斜哑铃卧推","sets":4,"reps":"8-10","duration":"","note":""},{"name":"杠铃划船","sets":4,"reps":"8-10","duration":"","note":""},{"name":"站姿推举","sets":3,"reps":"8-10","duration":"","note":""},{"name":"面拉","sets":3,"reps":"15","duration":"","note":""},{"name":"哑铃侧平举","sets":3,"reps":"12-15","duration":"","note":""},{"name":"俯卧撑","sets":2,"reps":"力竭前2次","duration":"","note":""}]', '胸、背阔、肩、手臂各拉伸30秒', '上肢B：主项4×6-10，辅助3×8-12；组间休息90秒；进度：同重量做满上限次数后下次加重', '[{"slot":"breakfast","time":"09:00","place":"早餐摊","food":"小笼包4个 + 茶叶蛋1个 + 无糖豆浆","portion":"包子4个、蛋1个、豆浆1杯","kcal":450,"protein":22,"howToOrder":"包子选鲜肉/菜肉的，不要油煎生煎；不蘸醋以外的酱","alternatives":["馄饨1小碗（不加猪油）+ 茶叶蛋1个","菜包2个 + 茶叶蛋2个 + 无糖豆浆"]},{"slot":"lunch","time":"12:30","place":"外卖","food":"黄焖鸡米饭（去皮、汤汁少）","portion":"鸡肉1份、米饭半份（约100g）","kcal":650,"protein":38,"howToOrder":"备注「鸡肉去皮、少汤汁、米饭少一半」，汤汁别拌饭；加一份烫青菜","alternatives":["香菇滑鸡饭（米饭减半）","台式卤肉饭换鸡腿饭（去皮、米饭减半）"]},{"slot":"snack","time":"16:00","place":"工位","food":"纯牛奶 + 全麦饼干2片","portion":"牛奶250ml、饼干2片","kcal":210,"protein":10,"howToOrder":"饼干看配料表第一位是全麦粉、糖不在前三位","alternatives":["无糖酸奶 + 苹果","即食鸡胸肉1袋"]},{"slot":"dinner","time":"17:30-18:30","place":"外卖","food":"宫保鸡丁（少油少糖）+ 蒜蓉西兰花 + 米饭","portion":"鸡丁1份、西兰花1份、米饭半份（约100g）","kcal":560,"protein":34,"howToOrder":"备注「少油少糖、花生少放」；西兰花备注少油","alternatives":["青椒炒牛肉 + 白灼菜心 + 米饭减半","小炒鸡胸肉 + 清炒时蔬 + 米饭减半"]},{"slot":"after_home","time":"21:30","place":"家里","food":"不饿就不吃，喝杯温水","portion":"—","kcal":0,"protein":0,"howToOrder":"真饿了再从替换里选一样","alternatives":["纯牛奶1盒","无糖酸奶1杯"]}]', '周四：上肢B，侧平举用轻重量', UNIX_TIMESTAMP(), UNIX_TIMESTAMP(), 0
FROM `fitness_template` t WHERE t.`code` = 'advanced' AND t.`deleted_at` = 0
