SELECT t.`id`, 6, '', 2, '08:00-09:00', 10000, '慢跑/慢骑5分钟', '[{"name":"间歇（跑步机或单车）","sets":8,"reps":"1分钟快 + 1分钟慢","duration":"","note":"快段约8分力，慢段走/慢骑恢复"},{"name":"放松慢走","sets":0,"reps":"","duration":"5分钟","note":""}]', '小腿、大腿前后侧各拉伸30秒', '总时长约25分钟；膝盖不适换单车', '[{"slot":"breakfast","time":"09:00","place":"早餐摊","food":"杂粮煎饼（加蛋、不要薄脆、酱少）+ 纯牛奶","portion":"煎饼1个、牛奶250ml","kcal":430,"protein":20,"howToOrder":"「加一个蛋、不要薄脆、酱刷一半」，薄脆换生菜","alternatives":["鸡蛋灌饼（少酱）+ 无糖豆浆","玉米1根 + 茶叶蛋2个 + 无糖豆浆"]},{"slot":"lunch","time":"12:30","place":"食堂","food":"一荤两素（去皮鸡腿/清蒸鱼/瘦牛肉）+ 米饭","portion":"荤菜1份、素菜2份、米饭半份（约100g）","kcal":620,"protein":35,"howToOrder":"荤菜挑清蒸/白灼/卤的，素菜挑看起来不油的；米饭盛半碗；汤只喝清汤","alternatives":["两荤一素（不要油炸）+ 米饭减半","番茄牛腩 + 清炒时蔬 + 米饭减半"]},{"slot":"snack","time":"16:00","place":"工位","food":"茶叶蛋1个 + 黄瓜1根","portion":"蛋1个、黄瓜1根","kcal":110,"protein":7,"howToOrder":"黄瓜可以提前在便利店/超市买好放工位","alternatives":["无糖酸奶1杯","即食鸡胸肉半袋 + 小番茄"]},{"slot":"dinner","time":"17:30-18:30","place":"食堂","food":"一荤两素（白切鸡/卤牛肉）+ 玉米或红薯","portion":"荤菜1份、素菜2份、玉米1根","kcal":520,"protein":34,"howToOrder":"晚饭主食换成玉米/红薯，荤菜挑白切/卤的","alternatives":["清蒸鱼 + 两素 + 米饭减半","番茄牛腩 + 青菜 + 红薯1个"]},{"slot":"after_home","time":"21:30","place":"家里","food":"无糖豆浆1盒","portion":"250ml","kcal":90,"protein":7,"howToOrder":"常温盒装备几盒在家","alternatives":["纯牛奶1盒","水煮蛋2个"]}]', '周六：间歇强度高，练前别空腹太久', UNIX_TIMESTAMP(), UNIX_TIMESTAMP(), 0
