SELECT t.`id`, 6, '', 2, '21:45-22:45', 8000, '慢走3-5分钟，逐渐加速到目标强度', '[{"name":"户外快走或骑车","sets":0,"reps":"","duration":"40分钟","note":"中等强度：能说完整句子但唱不了歌"}]', '小腿、大腿前后侧各拉伸30秒', '周末可以白天做，时间灵活', '[{"slot":"breakfast","time":"09:00","place":"早餐摊","food":"杂粮煎饼（加蛋、不要薄脆、酱少）+ 纯牛奶","portion":"煎饼1个、牛奶250ml","kcal":430,"protein":20,"howToOrder":"「加一个蛋、不要薄脆、酱刷一半」，薄脆换生菜","alternatives":["鸡蛋灌饼（少酱）+ 无糖豆浆","玉米1根 + 茶叶蛋2个 + 无糖豆浆"]},{"slot":"lunch","time":"12:30","place":"食堂","food":"一荤两素（去皮鸡腿/清蒸鱼/瘦牛肉）+ 米饭","portion":"荤菜1份、素菜2份、米饭半份（约100g）","kcal":620,"protein":35,"howToOrder":"荤菜挑清蒸/白灼/卤的，素菜挑看起来不油的；米饭盛半碗；汤只喝清汤","alternatives":["两荤一素（不要油炸）+ 米饭减半","番茄牛腩 + 清炒时蔬 + 米饭减半"]},{"slot":"snack","time":"16:00","place":"工位","food":"茶叶蛋1个 + 黄瓜1根","portion":"蛋1个、黄瓜1根","kcal":110,"protein":7,"howToOrder":"黄瓜可以提前在便利店/超市买好放工位","alternatives":["无糖酸奶1杯","即食鸡胸肉半袋 + 小番茄"]},{"slot":"dinner","time":"18:00","place":"食堂","food":"一荤两素（白切鸡/卤牛肉）+ 玉米或红薯","portion":"荤菜1份、素菜2份、玉米1根","kcal":520,"protein":34,"howToOrder":"晚饭主食换成玉米/红薯，荤菜挑白切/卤的","alternatives":["清蒸鱼 + 两素 + 米饭减半","番茄牛腩 + 青菜 + 红薯1个"]},{"slot":"after_home","time":"22:50","place":"家里","food":"练后：纯牛奶1盒 + 水煮蛋1个","portion":"牛奶250ml、蛋1个","kcal":220,"protein":14,"howToOrder":"练完半小时内吃完，23:45前睡；不要练完再点外卖","alternatives":["无糖酸奶1杯 + 水煮蛋1个","即食鸡胸肉半袋 + 纯牛奶"]}]', '周六：白天练也行，记得打卡', UNIX_TIMESTAMP(), UNIX_TIMESTAMP(), 0
