SELECT t.`id`, 1, '', 1, '20分钟，时间灵活', 7000, '原地踏步3分钟 + 开合跳20次 + 髋绕环、肩绕环各10次', '[{"name":"自重深蹲","sets":3,"reps":"15","duration":"","note":""},{"name":"俯卧撑","sets":3,"reps":"8-12","duration":"","note":"做不了就跪姿"},{"name":"椅子臂屈伸","sets":3,"reps":"10","duration":"","note":""},{"name":"原地箭步蹲","sets":3,"reps":"10/侧","duration":"","note":""},{"name":"平板支撑","sets":3,"reps":"","duration":"30秒","note":""}]', '大腿前后侧、臀部、胸肩各拉伸30秒，共5-8分钟', '20分钟循环：以下动作做完一轮休息1分钟，共3轮；酒店房间/家里都能做', '[{"slot":"breakfast","time":"09:00","place":"便利店","food":"茶叶蛋2个 + 无糖豆浆1盒 + 全麦面包1片","portion":"蛋2个、豆浆250ml、面包1片","kcal":380,"protein":25,"howToOrder":"热柜拿茶叶蛋；冷柜豆浆认准「无糖」；面包看配料表第一位是全麦粉","alternatives":["鸡蛋火腿三明治1个 + 无糖豆浆","玉米1根 + 茶叶蛋2个 + 纯牛奶"]},{"slot":"lunch","time":"12:30","place":"外卖","food":"轻食鸡胸肉沙拉碗 + 糙米饭","portion":"鸡胸150g、蔬菜1大份、米饭半份（约100g）","kcal":550,"protein":40,"howToOrder":"蛋白选鸡胸/牛肉，酱汁选油醋汁并备注「酱单独放」只用一半；主食加糙米","alternatives":["牛肉藜麦碗（酱单独放）","虾仁滑蛋饭（米饭减半）+ 一份烫青菜"]},{"slot":"snack","time":"16:00","place":"工位","food":"无糖酸奶1杯 + 苹果1个","portion":"酸奶100g、苹果1个","kcal":180,"protein":8,"howToOrder":"便利店冷柜选无添加糖酸奶","alternatives":["纯牛奶250ml + 橙子1个","茶叶蛋1个 + 黄瓜1根"]},{"slot":"dinner","time":"17:30-18:30","place":"食堂","food":"清蒸鱼 + 两份青菜 + 杂粮饭","portion":"鱼1份、青菜2份、米饭半份（约100g）","kcal":500,"protein":35,"howToOrder":"没有清蒸鱼就选白灼虾/卤牛肉；青菜挑少油的；杂粮饭盛半碗","alternatives":["卤牛肉 + 两素 + 米饭减半","番茄炒蛋 + 白切鸡 + 青菜（不要米饭换玉米）"]},{"slot":"after_home","time":"21:30","place":"家里","food":"纯牛奶1盒","portion":"250ml","kcal":150,"protein":8,"howToOrder":"到家不吃正餐，饿就喝牛奶","alternatives":["无糖酸奶1杯","水煮蛋2个"]}]', '周一：忙也别跳早饭，便利店5分钟搞定', UNIX_TIMESTAMP(), UNIX_TIMESTAMP(), 0
