INSERT INTO `fitness_template_day` (`template_id`, `weekday`, `plan_date`, `training_type`, `training_time`, `step_goal`, `warmup`, `exercises`, `stretch`, `training_note`, `meals`, `tip`, `created_at`, `updated_at`, `deleted_at`)
SELECT t.`id`, 1, '', 1, '08:00-09:00', 10000, '跑步机快走5分钟 + 动态拉伸（开合跳、髋绕环、肩绕环各10次）+ 第一个动作空杆/轻重量做2组', '[{"name":"保加利亚分腿蹲","sets":3,"reps":"10-12/侧","duration":"","note":""},{"name":"臀推","sets":3,"reps":"10-12","duration":"","note":""},{"name":"上斜哑铃卧推","sets":3,"reps":"10-12","duration":"","note":""},{"name":"坐姿划船","sets":3,"reps":"10-12","duration":"","note":""},{"name":"阿诺德推举","sets":3,"reps":"10-12","duration":"","note":""},{"name":"坡度走","sets":0,"reps":"","duration":"20分钟","note":"坡度8-10、速度5km/h"}]', '大腿前后侧、臀部、胸肩各拉伸30秒，共5-8分钟', '换动作刺激：保加利亚分腿蹲/臀推/上斜卧推/坐姿划船/阿诺德推举，3×10-12；练完坡度走20分钟', '[{"slot":"breakfast","time":"09:00","place":"便利店","food":"茶叶蛋2个 + 无糖豆浆1盒 + 全麦面包1片","portion":"蛋2个、豆浆250ml、面包1片","kcal":380,"protein":25,"howToOrder":"热柜拿茶叶蛋；冷柜豆浆认准「无糖」；面包看配料表第一位是全麦粉","alternatives":["鸡蛋火腿三明治1个 + 无糖豆浆","玉米1根 + 茶叶蛋2个 + 纯牛奶"]},{"slot":"lunch","time":"12:30","place":"外卖","food":"轻食鸡胸肉沙拉碗 + 糙米饭","portion":"鸡胸150g、蔬菜1大份、米饭1/3份（约70g），或换成1根玉米","kcal":480,"protein":40,"howToOrder":"蛋白选鸡胸/牛肉，酱汁选油醋汁并备注「酱单独放」只用一半；主食加糙米","alternatives":["牛肉藜麦碗（酱单独放）","虾仁滑蛋饭（米饭减半）+ 一份烫青菜"]},{"slot":"snack","time":"16:00","place":"工位","food":"无糖酸奶1杯 + 苹果1个","portion":"酸奶100g、苹果1个","kcal":180,"protein":8,"howToOrder":"便利店冷柜选无添加糖酸奶","alternatives":["纯牛奶250ml + 橙子1个","茶叶蛋1个 + 黄瓜1根"]},{"slot":"dinner","time":"17:30-18:30","place":"食堂","food":"清蒸鱼 + 两份青菜 + 杂粮饭","portion":"鱼1份、青菜2份、米饭1/3份（约70g），或换成1根玉米","kcal":430,"protein":35,"howToOrder":"没有清蒸鱼就选白灼虾/卤牛肉；青菜挑少油的；杂粮饭盛半碗","alternatives":["卤牛肉 + 两素 + 米饭减半","番茄炒蛋 + 白切鸡 + 青菜（不要米饭换玉米）"]},{"slot":"after_home","time":"21:30","place":"家里","food":"纯牛奶1盒","portion":"250ml","kcal":150,"protein":8,"howToOrder":"到家不吃正餐，饿就喝牛奶","alternatives":["无糖酸奶1杯","水煮蛋2个"]}]', '周一：平台期很正常，按计划多动一点', UNIX_TIMESTAMP(), UNIX_TIMESTAMP(), 0
FROM `fitness_template` t WHERE t.`code` = 'plateau' AND t.`deleted_at` = 0
ON DUPLICATE KEY UPDATE `fitness_template_day`.`id` = `fitness_template_day`.`id`;
INSERT INTO `fitness_template_day` (`template_id`, `weekday`, `plan_date`, `training_type`, `training_time`, `step_goal`, `warmup`, `exercises`, `stretch`, `training_note`, `meals`, `tip`, `created_at`, `updated_at`, `deleted_at`)
SELECT t.`id`, 2, '', 2, '08:00-09:00', 10000, '慢走3-5分钟，逐渐加速到目标强度', '[{"name":"坡度走或椭圆机","sets":0,"reps":"","duration":"45分钟","note":"中等强度：能说完整句子但唱不了歌"}]', '小腿、大腿前后侧各拉伸30秒', '比平时多10分钟，强度不变', '[{"slot":"breakfast","time":"09:00","place":"早餐摊","food":"鸡蛋灌饼（不刷甜面酱、少油）+ 无糖豆浆","portion":"灌饼1个、豆浆1杯","kcal":420,"protein":18,"howToOrder":"跟摊主说「酱少刷、不要辣条/火腿肠」，加一个蛋；豆浆要不加糖的","alternatives":["杂粮煎饼（加蛋不加薄脆）+ 无糖豆浆","肉包1个 + 茶叶蛋1个 + 无糖豆浆"]},{"slot":"lunch","time":"12:30","place":"外卖","food":"清汤牛肉面（加牛肉、面减半）+ 烫青菜","portion":"牛肉加量、面条半份、青菜1份（主食再少两口）","kcal":550,"protein":35,"howToOrder":"选清汤不选红油，「加一份牛肉、面少一半」；汤喝两口就停","alternatives":["番茄牛肉粉（粉减半）","鸡丝凉面换鸡丝汤面（面减半、加蛋）"]},{"slot":"snack","time":"16:00","place":"便利店","food":"即食鸡胸肉1袋","portion":"约100g","kcal":130,"protein":22,"howToOrder":"选原味/黑椒，避开蜜汁、烧烤味（糖多）","alternatives":["茶叶蛋2个","卤豆干1小包 + 纯牛奶"]},{"slot":"dinner","time":"17:30-18:30","place":"外卖","food":"小份酸菜鱼（不喝汤）+ 米饭","portion":"鱼片1份、米饭1/3份（约70g），或换成1根玉米","kcal":490,"protein":36,"howToOrder":"选小份/单人份，「少油」；鱼片和菜捞着吃，汤不喝","alternatives":["水煮鱼换清汤鱼片（小份）","番茄龙利鱼饭（米饭减半）"]},{"slot":"after_home","time":"21:30","place":"家里","food":"水煮蛋2个","portion":"2个","kcal":140,"protein":12,"howToOrder":"周末一次煮好一盒放冰箱","alternatives":["纯牛奶1盒","无糖酸奶1杯"]}]', '周二：步数目标10000，午饭后走15分钟', UNIX_TIMESTAMP(), UNIX_TIMESTAMP(), 0
FROM `fitness_template` t WHERE t.`code` = 'plateau' AND t.`deleted_at` = 0
ON DUPLICATE KEY UPDATE `fitness_template_day`.`id` = `fitness_template_day`.`id`;
INSERT INTO `fitness_template_day` (`template_id`, `weekday`, `plan_date`, `training_type`, `training_time`, `step_goal`, `warmup`, `exercises`, `stretch`, `training_note`, `meals`, `tip`, `created_at`, `updated_at`, `deleted_at`)
SELECT t.`id`, 3, '', 1, '08:00-09:00', 10000, '跑步机快走5分钟 + 动态拉伸（开合跳、髋绕环、肩绕环各10次）+ 第一个动作空杆/轻重量做2组', '[{"name":"高脚杯深蹲（停顿2秒）","sets":3,"reps":"10","duration":"","note":""},{"name":"单腿罗马尼亚硬拉","sets":3,"reps":"10/侧","duration":"","note":""},{"name":"俯卧撑（脚抬高）","sets":3,"reps":"8-12","duration":"","note":""},{"name":"高位下拉","sets":3,"reps":"10-12","duration":"","note":""},{"name":"哑铃侧平举","sets":3,"reps":"15","duration":"","note":""},{"name":"坡度走","sets":0,"reps":"","duration":"20分钟","note":""}]', '大腿前后侧、臀部、胸肩各拉伸30秒，共5-8分钟', '换动作刺激：保加利亚分腿蹲/臀推/上斜卧推/坐姿划船/阿诺德推举，3×10-12；练完坡度走20分钟', '[{"slot":"breakfast","time":"09:00","place":"便利店","food":"鸡胸肉三明治 + 纯牛奶","portion":"三明治1个、牛奶250ml","kcal":430,"protein":30,"howToOrder":"选夹鸡胸/鸡蛋的三明治，避开沙拉酱很厚、夹炸物的；牛奶选纯牛奶不选乳饮料","alternatives":["金枪鱼饭团1个 + 茶叶蛋1个 + 纯牛奶","即食鸡胸肉1袋 + 全麦面包2片"]},{"slot":"lunch","time":"12:30","place":"外卖","food":"木桶饭（清蒸鱼/香菇鸡 + 青菜）","portion":"主菜1份、青菜1份、米饭1/3份（约70g），或换成1根玉米","kcal":530,"protein":36,"howToOrder":"主菜挑清蒸鱼/香菇鸡/番茄牛腩，避开红烧肉/干锅；备注「米饭少一半」","alternatives":["煲仔饭换卤牛肉饭（米饭减半）","日式鸡腿饭（去皮、酱少、米饭减半）"]},{"slot":"snack","time":"16:00","place":"工位","food":"原味坚果1小包 + 无糖豆浆","portion":"坚果20g、豆浆250ml","kcal":210,"protein":10,"howToOrder":"坚果只吃一小包（每日坚果那种），别开大罐","alternatives":["纯牛奶 + 苹果","无糖酸奶 + 香蕉半根"]},{"slot":"dinner","time":"17:30-18:30","place":"外卖","food":"照烧鸡腿饭（去皮、酱少）+ 味增汤","portion":"鸡腿1只、米饭1/3份（约70g），或换成1根玉米","kcal":490,"protein":33,"howToOrder":"备注「鸡腿去皮、照烧汁少放、米饭少一半」","alternatives":["日式烤鱼定食（米饭减半）","寿司拼盘8个 + 味增汤"]},{"slot":"after_home","time":"21:30","place":"家里","food":"无糖酸奶1杯","portion":"150g","kcal":120,"protein":7,"howToOrder":"选配料表只有生牛乳+菌种的","alternatives":["纯牛奶1盒","水煮蛋1个 + 黄瓜"]}]', '周三：主食再少两口，蛋白质别减', UNIX_TIMESTAMP(), UNIX_TIMESTAMP(), 0
FROM `fitness_template` t WHERE t.`code` = 'plateau' AND t.`deleted_at` = 0
ON DUPLICATE KEY UPDATE `fitness_template_day`.`id` = `fitness_template_day`.`id`;
