SELECT t.`id`, 7, '', 3, '', 10000, '', '[{"name":"饭后散步","sets":0,"reps":"","duration":"40分钟","note":"休息日也尽量走到10000步"}]', '', '', '[{"slot":"breakfast","time":"09:00","place":"便利店","food":"玉米1根 + 茶叶蛋2个 + 纯牛奶","portion":"玉米1根、蛋2个、牛奶250ml","kcal":400,"protein":24,"howToOrder":"热柜玉米选甜糯都行，不刷黄油；牛奶也可换无糖豆浆","alternatives":["全麦面包2片 + 茶叶蛋2个 + 纯牛奶","鸡肉饭团1个 + 无糖豆浆"]},{"slot":"lunch","time":"12:30","place":"外卖","food":"麻辣烫（清汤/番茄锅，荤素各半）","portion":"荤菜约150g、素菜约250g、主食少量（主食再少两口）","kcal":500,"protein":35,"howToOrder":"锅底选清汤或番茄；荤选鸡胸/虾滑/牛肉/豆腐，少丸子类；主食选玉米或少量面，不要宽粉/方便面；不喝汤","alternatives":["关东煮（鸡蛋+海带+豆腐+鸡肉串）+ 饭团","冒菜（清汤锅、荤素各半、米饭减半）"]},{"slot":"snack","time":"16:00","place":"工位","food":"无糖豆浆 + 橙子1个","portion":"豆浆250ml、橙子1个","kcal":150,"protein":8,"howToOrder":"同事点下午茶时就拿这一份顶上","alternatives":["纯牛奶 + 小香蕉","茶叶蛋1个 + 苹果"]},{"slot":"dinner","time":"17:30-18:30","place":"外卖","food":"潮汕牛肉丸汤粉（加牛肉、粿条减半）","portion":"牛肉+牛肉丸、粿条半份、青菜（主食再少两口）","kcal":470,"protein":34,"howToOrder":"「加一份鲜切牛肉、粿条少一半、多放青菜」，沙茶酱少蘸","alternatives":["牛肉火锅简餐（清汤、少蘸料）","鱼片粥（加青菜）+ 茶叶蛋1个"]},{"slot":"after_home","time":"21:30","place":"家里","food":"纯牛奶1盒","portion":"250ml","kcal":150,"protein":8,"howToOrder":"别在这个点吃泡面/外卖夜宵","alternatives":["水煮蛋2个","无糖酸奶1杯"]}]', '周日：称体重看7日均值，2周后回原模板', UNIX_TIMESTAMP(), UNIX_TIMESTAMP(), 0
