SELECT t.`id`, 2, '', 3, '', 8000, '', '[{"name":"饭后散步","sets":0,"reps":"","duration":"30分钟","note":"正常活动，想动可以快走"}]', '', '', '[{"slot":"breakfast","time":"09:00","place":"早餐摊","food":"鸡蛋灌饼（不刷甜面酱、少油）+ 无糖豆浆","portion":"灌饼1个、豆浆1杯","kcal":480,"protein":18,"howToOrder":"跟摊主说「酱少刷、不要辣条/火腿肠」，加一个蛋；豆浆要不加糖的","alternatives":["杂粮煎饼（加蛋不加薄脆）+ 无糖豆浆","肉包1个 + 茶叶蛋1个 + 无糖豆浆"]},{"slot":"lunch","time":"12:30","place":"外卖","food":"清汤牛肉面（加牛肉、面减半）+ 烫青菜","portion":"牛肉加量、面条半份、青菜1份（主食正常吃）","kcal":700,"protein":35,"howToOrder":"选清汤不选红油，「加一份牛肉、面少一半」；汤喝两口就停","alternatives":["番茄牛肉粉（粉减半）","鸡丝凉面换鸡丝汤面（面减半、加蛋）"]},{"slot":"snack","time":"16:00","place":"便利店","food":"即食鸡胸肉1袋","portion":"约100g","kcal":190,"protein":22,"howToOrder":"选原味/黑椒，避开蜜汁、烧烤味（糖多）","alternatives":["茶叶蛋2个","卤豆干1小包 + 纯牛奶"]},{"slot":"dinner","time":"17:30-18:30","place":"外卖","food":"小份酸菜鱼（不喝汤）+ 米饭","portion":"鱼片1份、米饭1份（约200g）","kcal":680,"protein":36,"howToOrder":"选小份/单人份，「少油」；鱼片和菜捞着吃，汤不喝","alternatives":["水煮鱼换清汤鱼片（小份）","番茄龙利鱼饭（米饭减半）"]},{"slot":"after_home","time":"21:30","place":"家里","food":"水煮蛋2个","portion":"2个","kcal":140,"protein":12,"howToOrder":"周末一次煮好一盒放冰箱","alternatives":["纯牛奶1盒","无糖酸奶1杯"]}]', '周二：主食可以正常吃，但油炸和甜饮料照样少碰', UNIX_TIMESTAMP(), UNIX_TIMESTAMP(), 0
