SELECT t.`id`, 6, '', 3, '', 8000, '', '[{"name":"饭后散步","sets":0,"reps":"","duration":"40分钟","note":"可选：户外有氧30-40分钟，做了就在打卡里记步数"}]', '', '', '[{"slot":"breakfast","time":"09:00","place":"早餐摊","food":"杂粮煎饼（加蛋、不要薄脆、酱少）+ 纯牛奶","portion":"煎饼1个、牛奶250ml","kcal":490,"protein":20,"howToOrder":"「加一个蛋、不要薄脆、酱刷一半」，薄脆换生菜","alternatives":["鸡蛋灌饼（少酱）+ 无糖豆浆","玉米1根 + 茶叶蛋2个 + 无糖豆浆"]},{"slot":"lunch","time":"12:30","place":"食堂","food":"一荤两素（去皮鸡腿/清蒸鱼/瘦牛肉）+ 米饭","portion":"荤菜1份、素菜2份、米饭1份（约200g）","kcal":740,"protein":35,"howToOrder":"荤菜挑清蒸/白灼/卤的，素菜挑看起来不油的；米饭盛半碗；汤只喝清汤","alternatives":["两荤一素（不要油炸）+ 米饭减半","番茄牛腩 + 清炒时蔬 + 米饭减半"]},{"slot":"snack","time":"16:00","place":"工位","food":"茶叶蛋1个 + 黄瓜1根","portion":"蛋1个、黄瓜1根","kcal":170,"protein":7,"howToOrder":"黄瓜可以提前在便利店/超市买好放工位","alternatives":["无糖酸奶1杯","即食鸡胸肉半袋 + 小番茄"]},{"slot":"dinner","time":"17:30-18:30","place":"食堂","food":"一荤两素（白切鸡/卤牛肉）+ 玉米或红薯","portion":"荤菜1份、素菜2份、玉米1根（主食正常吃）","kcal":620,"protein":34,"howToOrder":"晚饭主食换成玉米/红薯，荤菜挑白切/卤的","alternatives":["清蒸鱼 + 两素 + 米饭减半","番茄牛腩 + 青菜 + 红薯1个"]},{"slot":"after_home","time":"21:30","place":"家里","food":"无糖豆浆1盒","portion":"250ml","kcal":90,"protein":7,"howToOrder":"常温盒装备几盒在家","alternatives":["纯牛奶1盒","水煮蛋2个"]}]', '周六：体重涨超1kg就回减脂标准', UNIX_TIMESTAMP(), UNIX_TIMESTAMP(), 0
FROM `fitness_template` t WHERE t.`code` = 'maintain' AND t.`deleted_at` = 0
ON DUPLICATE KEY UPDATE `fitness_template_day`.`id` = `fitness_template_day`.`id`;
INSERT INTO `fitness_template_day` (`template_id`, `weekday`, `plan_date`, `training_type`, `training_time`, `step_goal`, `warmup`, `exercises`, `stretch`, `training_note`, `meals`, `tip`, `created_at`, `updated_at`, `deleted_at`)
SELECT t.`id`, 7, '', 3, '', 8000, '', '[{"name":"饭后散步","sets":0,"reps":"","duration":"40分钟","note":"休息日"}]', '', '', '[{"slot":"breakfast","time":"09:00","place":"便利店","food":"玉米1根 + 茶叶蛋2个 + 纯牛奶","portion":"玉米1根、蛋2个、牛奶250ml","kcal":460,"protein":24,"howToOrder":"热柜玉米选甜糯都行，不刷黄油；牛奶也可换无糖豆浆","alternatives":["全麦面包2片 + 茶叶蛋2个 + 纯牛奶","鸡肉饭团1个 + 无糖豆浆"]},{"slot":"lunch","time":"12:30","place":"外卖","food":"麻辣烫（清汤/番茄锅，荤素各半）","portion":"荤菜约150g、素菜约250g、主食少量（主食正常吃）","kcal":650,"protein":35,"howToOrder":"锅底选清汤或番茄；荤选鸡胸/虾滑/牛肉/豆腐，少丸子类；主食选玉米或少量面，不要宽粉/方便面；不喝汤","alternatives":["关东煮（鸡蛋+海带+豆腐+鸡肉串）+ 饭团","冒菜（清汤锅、荤素各半、米饭减半）"]},{"slot":"snack","time":"16:00","place":"工位","food":"无糖豆浆 + 橙子1个","portion":"豆浆250ml、橙子1个","kcal":210,"protein":8,"howToOrder":"同事点下午茶时就拿这一份顶上","alternatives":["纯牛奶 + 小香蕉","茶叶蛋1个 + 苹果"]},{"slot":"dinner","time":"17:30-18:30","place":"外卖","food":"潮汕牛肉丸汤粉（加牛肉、粿条减半）","portion":"牛肉+牛肉丸、粿条半份、青菜（主食正常吃）","kcal":620,"protein":34,"howToOrder":"「加一份鲜切牛肉、粿条少一半、多放青菜」，沙茶酱少蘸","alternatives":["牛肉火锅简餐（清汤、少蘸料）","鱼片粥（加青菜）+ 茶叶蛋1个"]},{"slot":"after_home","time":"21:30","place":"家里","food":"纯牛奶1盒","portion":"250ml","kcal":150,"protein":8,"howToOrder":"别在这个点吃泡面/外卖夜宵","alternatives":["水煮蛋2个","无糖酸奶1杯"]}]', '周日：保持作息，享受成果', UNIX_TIMESTAMP(), UNIX_TIMESTAMP(), 0
